from ipaddress import IPv6Address, ip_address
from taf.hw.hp.redfish.services.auth.authorization import Authorization
from taf.hw.hp.redfish.exceptions import RedfishVersionNotSupported
from taf.hw.hp.redfish.utils.logger import Logger
from taf.hw.hp.redfish.interfaces.redfish_hpedl110g11bmc import RedfishHpeDL110G11BMC
from taf.hw.hp.redfish.interfaces.redfish_hpedl360bmc import RedfishHpeDL360BMC
from taf.hw.hp.redfish.interfaces.redfish_hpedl110g12bmc import RedfishHpeDL110G12BMC
from taf.hw.hp.redfish.interfaces.redfish_hpedl470bmc import RedfishHpeDL470BMC


class ConnectionDetails(object):
    def __init__(self, host, username, password, port='443', alias=None):
        """
        :param int status: Status code based on HTTP Status Codes
        :param dict data: Data returned by endpoint function
        """
        self.protocol = 'https://'
        self.host = host
        self.port = port
        self.username = username
        self.password = password

        self.base_url = '{protocol}{host}:{port}'.format(protocol=self.protocol,
                                                         host=self.host,
                                                         port=self.port)

        alias_name = alias if alias else 'default'
        logger_name = 'taf.hw.hp.redfish.' + alias_name
        self.logger = Logger(logger_name=logger_name, file_log_name='taf.hw.hp.redfish.log')

    @staticmethod
    def format_host_for_base_url(host):
        host = host.rstrip("]").lstrip("[")
        try:
            if isinstance(ip_address(host), IPv6Address):
                return '[{}]'.format(host)
            else:
                return host
        except (ValueError, TypeError):
            return host


class SupportedRedfishVersions:
    redfish_versions = {
        'dl110g11_bmc': RedfishHpeDL110G11BMC,
        'dl360_bmc': RedfishHpeDL360BMC,
        'dl110g12_bmc': RedfishHpeDL110G12BMC,
        'dl470_bmc': RedfishHpeDL470BMC
        }

    @classmethod
    def is_supported(cls, redfish_version):
        return redfish_version in cls.redfish_versions

    @classmethod
    def get_redfish_class(cls, redfish_version):
        return cls.redfish_versions.get(redfish_version)


class RedfishProvider(object):
    @classmethod
    def create_redfish(cls, host, username, password, port='443', redfish_version='dl110g11_bmc', alias=None):
        if SupportedRedfishVersions.is_supported(redfish_version):
            redfish_class = SupportedRedfishVersions.get_redfish_class(redfish_version)
        else:
            raise RedfishVersionNotSupported(f'Redfish version {redfish_version} is not supported')
        host = ConnectionDetails.format_host_for_base_url(host)
        token_details = Authorization.get_access_token_details(host, port, username, password)
        con_details = ConnectionDetails(host, username, password, port, alias)
        redfish = redfish_class(con_details, token_details)
        return redfish
